import { createClient } from "@supabase/supabase-js";
import dotenv from "dotenv";
dotenv.config();
var supabaseUrl = process.env.SUPABASE_URL || "";
var supabaseKey = process.env.SUPABASE_SECRET_KEY || "";
var client = null;
if (supabaseUrl && supabaseKey && supabaseUrl.startsWith("http")) {
  try {
    client = createClient(supabaseUrl, supabaseKey);
  } catch (error) {
    console.error("Failed to initialize Supabase client:", error);
  }
} else if (supabaseUrl || supabaseKey) {
  console.warn("Supabase URL or Key is invalid or missing. Ensure SUPABASE_URL starts with http:// or https://");
}
var supabase = client;

// backend/services/gemini.service.ts
import Papa from "papaparse";
var sessionHistory = {};
var GeminiService = class {
  static async handleChatStream(sessionId, question, datasetContext, currentFilters, currentState, onChunk) {
    const ai = getGeminiClient();
    if (!sessionHistory[sessionId]) {
      sessionHistory[sessionId] = [];
    }
    const history = sessionHistory[sessionId];
    let datasetData = datasetContext?.data || null;
    if (!datasetData) {
      try {
        let csvText = "";
        if (datasetContext?.storagePath && supabase) {
          console.log(`Downloading file from Supabase: ${datasetContext.storagePath}`);
          const { data, error } = await supabase.storage.from("insightiq-datasets").download(datasetContext.storagePath);
          if (error) {
            throw new Error(`Supabase download error: ${error.message}`);
          }
          csvText = await data.text();
        } else if (datasetContext?.downloadURL) {
          console.log(`Downloading file from: ${datasetContext.downloadURL}`);
          let url = datasetContext.downloadURL;
          if (url.startsWith("/")) {
            throw new Error("Cannot fetch relative URL from server.");
          }
          const res = await fetch(url);
          if (!res.ok) throw new Error(`Failed to fetch CSV: ${res.statusText}`);
          csvText = await res.text();
        }
        if (csvText) {
          const parsed = Papa.parse(csvText, { header: true, dynamicTyping: true, skipEmptyLines: true });
          if (parsed.errors.length && !parsed.data.length) {
            throw new Error(`CSV Parsing failed: ${parsed.errors[0].message}`);
          }
          datasetData = parsed.data;
          console.log("--- CSV LOADED ---");
          console.log(`Downloaded file: ${datasetContext?.name}`);
          console.log(`Rows parsed: ${datasetData.length}`);
          console.log(`Columns parsed: ${Object.keys(datasetData[0] || {}).length}`);
          datasetContext.data = datasetData;
        }
      } catch (err) {
        console.error("Error downloading/parsing CSV:", err);
        throw new Error(`Failed to load dataset: ${err.message}`);
      }
    } else if (datasetData) {
      console.log("--- CSV LOADED ---");
      console.log("Dataset provided in request payload.");
      console.log(`Rows parsed: ${datasetData.length}`);
    }
    const systemPrompt = buildAiSystemPrompt(datasetContext, history, currentFilters, currentState);
    try {
      console.log("Model name: gemini-3.6-flash");
      console.log("Prompt length:", systemPrompt.length + question.length);
      console.log("Dataset size (rows):", datasetContext?.data?.length || 0);
      const contents = [];
      let filteredHistory = [...history];
      while (filteredHistory.length > 0 && filteredHistory[0].role !== "user") {
        filteredHistory.shift();
      }
      for (const msg of filteredHistory) {
        contents.push({
          role: msg.role === "model" ? "model" : "user",
          parts: [{ text: msg.content }]
        });
      }
      contents.push({
        role: "user",
        parts: [{ text: question }]
      });
      const responseStream = await ai.models.generateContentStream({
        model: "gemini-3.6-flash",
        contents,
        config: {
          systemInstruction: systemPrompt
        }
      });
      let fullResponse = "";
      for await (const chunk of responseStream) {
        if (chunk.text) {
          fullResponse += chunk.text;
          onChunk(chunk.text);
        }
      }
      console.log("--- RESPONSE RECEIVED ---");
      console.log("Successfully completed Gemini stream");
      history.push({ role: "user", content: question });
      history.push({ role: "model", content: fullResponse });
      if (history.length > 20) {
        sessionHistory[sessionId] = history.slice(history.length - 20);
      }
      return fullResponse;
    } catch (error) {
      console.error("Gemini stream error:", error);
      if (error.status === 429 || error.message && error.message.includes("429")) {
        throw new Error("You have exceeded your Gemini API quota. Please try again in a few moments.");
      }
      throw error;
    }
  }
};

// backend/controllers/ai.controller.ts
var AiController = class {
  static async chat(req, res) {
    try {
      const { sessionId, question, datasetContext, currentFilters, currentState } = req.body;
      console.log("--- BACKEND RECEIVED ---");
      console.log("Incoming request:", question);
      console.log("Dataset URL:", datasetContext?.downloadURL || "N/A");
      console.log("Prompt:", question);
      if (!question) {
        return res.status(400).json({ success: false, error: "Question is required" });
      }
      const sId = sessionId || "default_session";
      res.setHeader("Content-Type", "text/event-stream");
      res.setHeader("Cache-Control", "no-cache");
      res.setHeader("Connection", "keep-alive");
      res.flushHeaders();
      if (!process.env.GEMINI_API_KEY) {
        res.write(`data: ${JSON.stringify({ error: "Gemini API is not configured. Add GEMINI_API_KEY to the server environment." })}

`);
        return res.end();
      }
      console.log("--- GEMINI CALLED ---");
      await GeminiService.handleChatStream(
        sId,
        question,
        datasetContext,
        currentFilters,
        currentState,
        (chunk) => {
          res.write(`data: ${JSON.stringify({ text: chunk })}

`);
        }
      );
      res.write(`data: [DONE]

`);
      res.end();
    } catch (error) {
      console.error("Chat controller error:", error);
      res.write(`data: ${JSON.stringify({ error: error.message || "Failed to generate response" })}

`);
      res.end();
    }
  }
};

// backend/controllers/copilot.controller.ts
import { Type } from "@google/genai";
var CopilotController = class {
  static async analyze(req, res) {
    try {
      const { query, schema, metricsSummary, files, currency, history } = req.body;
      if (!process.env.GEMINI_API_KEY) {
        return res.status(503).json({ error: "Gemini API is not configured. Add GEMINI_API_KEY to the server environment." });
      }
      const ai = getGeminiClient();
      const systemPrompt = `You are InsightIQ Copilot, an expert business analyst and data scientist.
You interpret user queries and determine what data operations are needed, and generate rigorous, business-oriented insights based on provided metrics.

Task:
1. Determine the user's intent.
2. If the user asks for a chart, table, or calculation that requires iterating over the dataset, YOU MUST include an "operations" block to compute it locally. Choose the appropriate visualType (bar, line, pie, table, metric).
3. Generate a highly professional, structured markdown explanation.

CRITICAL RULES FOR RESPONSES:
1. DATA ACCURACY: DO NOT invent, hallucinate, or fabricate ANY numeric values. ONLY use data explicitly existing in the metricsSummary or files.
2. STRUCTURE & HEADINGS: Do NOT use ALL-CAPS headings. Use Sentence case or normal Title Case (e.g., "Executive summary", "Key metrics"). Use standard Markdown headings (#, ##, ###).
3. METRICS PRESENTATION: Do not bury metrics in long sentences. Present them clearly, e.g.:
**Total Revenue**
${currency || "$"}18,93,947

4. FORMATTING: Format monetary values using the provided currency symbol (${currency || "$"}). Format large numbers with commas consistently (e.g. 1,457,849 or Indian format 14,57,849 if applicable). Format percentages clearly (e.g. 76.97%).
5. TABLES FOR TOP ITEMS: For Top Products or Categories, ALWAYS use a Markdown table. The UI will render it as a responsive data grid. Provide Rank, Name, Value, and % Contribution.
6. ACTIONABLE INSIGHTS: Use the pattern:
   - **Finding:** [What the data shows]
   - **Business Impact:** [Why it matters]
   - **Action:** [What to do]
7. RECOMMENDATIONS: Make them specific, data-backed, and prioritized. Prefix with **[High Priority]**, **[Medium Priority]**, **[Risk]**, or **[Opportunity]**.
8. DATA QUALITY: Be objective (e.g., "Data completeness: 100%"). Do not overstate confidence.
9. MISSING DATA: Gracefully skip unavailable metrics. Do not say "Error". State "Not available" if directly asked.
10. LENGTH: Adapt to the question. Short for simple queries, detailed for open-ended analysis.

Columns available: ${JSON.stringify(schema)}
Metrics summary: ${JSON.stringify(metricsSummary)}`;
      const contents = [];
      if (history && Array.isArray(history)) {
        let filteredHistory = [...history];
        while (filteredHistory.length > 0 && filteredHistory[0].role !== "user") {
          filteredHistory.shift();
        }
        for (const msg of filteredHistory) {
          contents.push({
            role: msg.role === "assistant" ? "model" : "user",
            parts: [{ text: msg.content }]
          });
        }
      }
      contents.push({ role: "user", parts: [{ text: query }] });
      if (files && files.length > 0) {
        for (const file of files) {
          contents[0].parts.push({
            inlineData: {
              mimeType: file.mimeType,
              data: file.data
            }
          });
        }
      }
      const response = await ai.models.generateContent({
        model: "gemini-3.6-flash",
        contents,
        config: {
          systemInstruction: systemPrompt,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              intent: { type: Type.STRING, description: "The intent of the user query" },
              visualType: { type: Type.STRING, description: "The type of visualization to generate" },
              explanation: { type: Type.STRING, description: "Markdown string containing your structured response" },
              operations: {
                type: Type.OBJECT,
                properties: {
                  metric: { type: Type.STRING, description: "The metric to analyze" },
                  agg: { type: Type.STRING, description: "Aggregation function" },
                  groupBy: { type: Type.STRING, description: "The column to group by" },
                  sort: { type: Type.STRING, description: "Sort direction" },
                  limit: { type: Type.INTEGER, description: "Limit number of results" }
                }
              }
            }
          }
        }
      });
      let responseText = response.text || "{}";
      try {
        res.json(JSON.parse(responseText));
      } catch (e) {
        const sanitizedText = responseText.replace(/[\u0000-\u001F]+/g, (match) => {
          if (match.includes("\n")) return "\\n";
          if (match.includes("\r")) return "\\r";
          if (match.includes("	")) return "\\t";
          return "";
        });
        res.json(JSON.parse(sanitizedText));
      }
    } catch (error) {
      console.error("Copilot controller error details:", error, "Stack:", error.stack);
      res.status(500).json({ error: error.message || "Failed to process query" });
    }
  }
};

